// Déclaration du type : une struct à champs nommés
struct Utilisateur {
    nom: String,
    age: u32,
    actif: bool,
}

fn main() {
    // Instanciation : on fournit une valeur pour chaque champ
    let alice = Utilisateur {
        nom: String::from("Alice"),
        age: 30,
        actif: true,
    };

    // Accès aux champs avec le point
    println!("{} a {} ans", alice.nom, alice.age);
}

struct Utilisateur {
    nom: String,
    age: u32,
    actif: bool,
}

// Le raccourci d'initialisation : quand les paramètres portent le
// même nom que les champs, on écrit juste `nom` au lieu de `nom: nom`.
fn creer(nom: String, age: u32) -> Utilisateur {
    Utilisateur {
        nom,          // raccourci pour `nom: nom`
        age,          // raccourci pour `age: age`
        actif: true,
    }
}

fn main() {
    let mut bob = creer(String::from("Bob"), 25);
    bob.age = 26;     // possible car `bob` est `mut`
    bob.actif = false;
    println!("{} a maintenant {} ans", bob.nom, bob.age);
}

// `derive(Debug)` génère l'affichage pour `{:?}`
#[derive(Debug)]
struct Point(i32, i32);   // struct tuple : champs par position

#[derive(Debug)]
struct Marqueur;          // struct unité : aucun champ

fn main() {
    let origine = Point(0, 0);
    println!("x vaut {}", origine.0);   // accès par position : .0, .1
    println!("{:?}", origine);          // affiche : Point(0, 0)

    let m = Marqueur;
    println!("{:?}", m);                // affiche : Marqueur
}

#[derive(Debug)]
struct Compteur {
    valeur: u32,
}

impl Compteur {
    // Fonction associée (pas de self) : sert de constructeur
    fn new() -> Compteur {
        Compteur { valeur: 0 }
    }

    // Méthode en lecture : `&self` emprunte sans modifier
    fn valeur(&self) -> u32 {
        self.valeur
    }

    // Méthode en écriture : `&mut self` modifie l'instance
    fn incrementer(&mut self) {
        self.valeur += 1;
    }
}

fn main() {
    // On appelle une fonction associée avec `::`
    let mut c = Compteur::new();
    c.incrementer();              // appel de méthode avec `.`
    c.incrementer();
    println!("valeur = {}", c.valeur());   // affiche : valeur = 2
}

