#[derive(Debug)]
struct Rectangle {
    largeur: u32,
    hauteur: u32,
}

impl Rectangle {
    // Fonction associée : le constructeur
    fn new(largeur: u32, hauteur: u32) -> Rectangle {
        Rectangle { largeur, hauteur }   // raccourci d'initialisation
    }

    // Méthode en lecture : `&self`, elle ne modifie rien
    fn aire(&self) -> u32 {
        self.largeur * self.hauteur
    }
}

fn main() {
    let r = Rectangle::new(3, 4);
    println!("aire = {}", r.aire());   // affiche : aire = 12
}
